from typing import List

def bird_code(arr: List[str]) -> List[str]:
    """Generate four-letter codes for common bird names based on specific rules. The codes are returned in uppercase and maintain the order of the input names."""
    return [create_code(split_name(name)) for name in arr]

def split_name(name: str) -> List[str]:
    """Split a bird name into words, treating hyphens as spaces."""
    return name.replace('-', ' ').split()

def create_code(words: List[str]) -> str:
    """Create a four-letter code based on the number of words in the bird name."""
    if len(words) == 1:
        return words[0][:4].upper()
    elif len(words) == 2:
        return words[0][:2].upper() + words[1][:2].upper()
